`timescale 1ns / 1ps
// =============================================================================
// compliance_tb  -  official riscv-tests rv32ui suite on rv32i_core_pipelined_full
//
// GENERATED FILE: the machine code of every test is embedded below, so no hex
// files or file paths are needed. Tests come from riscv-software-src/riscv-tests
// (isa/rv32ui), assembled with -march=rv32i and a minimal bare-metal environment
// (no CSRs / traps):
//   * text linked at 0x0 -> instruction memory
//   * data linked at 0x2000 -> data memory (its decoder only uses addr[11:2],
//     so 0x2000 aliases to word 0)
//   * pass/fail is a store to 'tohost' (0x2FF8 -> dmem word 1022):
//       1            = PASS
//       (n<<1)|1     = FAIL in sub-test n
// Not run: fence_i (needs FENCE.I and self-modifying code; core does not implement it).
//
// The TB loads imem/dmem by hierarchical writes, resets the core, runs until the
// tohost word becomes non-zero (or times out), and reports per test.
// =============================================================================
