    task automatic load_test(input int id);
        for (int i = 0; i < 1024; i++) begin ibuf[i] = NOP_I; dbuf[i] = 32'h0; end
        case (id)
            0: begin tname = "add"; load_add(); end
            1: begin tname = "addi"; load_addi(); end
            2: begin tname = "and"; load_and(); end
            3: begin tname = "andi"; load_andi(); end
            4: begin tname = "auipc"; load_auipc(); end
            5: begin tname = "beq"; load_beq(); end
            6: begin tname = "bge"; load_bge(); end
            7: begin tname = "bgeu"; load_bgeu(); end
            8: begin tname = "blt"; load_blt(); end
            9: begin tname = "bltu"; load_bltu(); end
            10: begin tname = "bne"; load_bne(); end
            11: begin tname = "jal"; load_jal(); end
            12: begin tname = "jalr"; load_jalr(); end
            13: begin tname = "lb"; load_lb(); end
            14: begin tname = "lbu"; load_lbu(); end
            15: begin tname = "ld_st"; load_ld_st(); end
            16: begin tname = "lh"; load_lh(); end
            17: begin tname = "lhu"; load_lhu(); end
            18: begin tname = "lui"; load_lui(); end
            19: begin tname = "lw"; load_lw(); end
            20: begin tname = "ma_data"; load_ma_data(); end
            21: begin tname = "or"; load_or(); end
            22: begin tname = "ori"; load_ori(); end
            23: begin tname = "sb"; load_sb(); end
            24: begin tname = "sh"; load_sh(); end
            25: begin tname = "simple"; load_simple(); end
            26: begin tname = "sll"; load_sll(); end
            27: begin tname = "slli"; load_slli(); end
            28: begin tname = "slt"; load_slt(); end
            29: begin tname = "slti"; load_slti(); end
            30: begin tname = "sltiu"; load_sltiu(); end
            31: begin tname = "sltu"; load_sltu(); end
            32: begin tname = "sra"; load_sra(); end
            33: begin tname = "srai"; load_srai(); end
            34: begin tname = "srl"; load_srl(); end
            35: begin tname = "srli"; load_srli(); end
            36: begin tname = "st_ld"; load_st_ld(); end
            37: begin tname = "sub"; load_sub(); end
            38: begin tname = "sw"; load_sw(); end
            39: begin tname = "xor"; load_xor(); end
            40: begin tname = "xori"; load_xori(); end
            default: tname = "?";
        endcase
    endtask

    function automatic logic [31:0] dmem_word(input int w);
        return {dut.u_dmem.g_bank[3].mem[w], dut.u_dmem.g_bank[2].mem[w],
                dut.u_dmem.g_bank[1].mem[w], dut.u_dmem.g_bank[0].mem[w]};
    endfunction

    task automatic run_one(input int id);
        int cyc;
        logic [31:0] th;
        load_test(id);
        rst_n = 1'b0;
        for (int i = 0; i < 1024; i++) begin
            dut.u_imem.mem[i]         = ibuf[i];
            dut.u_dmem.g_bank[0].mem[i] = dbuf[i][7:0];
            dut.u_dmem.g_bank[1].mem[i] = dbuf[i][15:8];
            dut.u_dmem.g_bank[2].mem[i] = dbuf[i][23:16];
            dut.u_dmem.g_bank[3].mem[i] = dbuf[i][31:24];
        end
        repeat (3) @(negedge clk);
        rst_n = 1'b1;
        cyc = 0;
        th  = 32'h0;
        while (th === 32'h0 && cyc < MAX_CYC) begin
            @(negedge clk); cyc++;
            th = dmem_word(TOHOST_W);
        end
        if (th === 32'h1) begin
            pass_cnt++;
            $display("[PASS] rv32ui-%-8s (%0d cycles)", tname, cyc);
        end else if (th === 32'h0) begin
            fail_cnt++;
            $error("[FAIL] rv32ui-%s: TIMEOUT after %0d cycles (pc=0x%08h)", tname, cyc, dut.pc_out);
        end else begin
            fail_cnt++;
            $error("[FAIL] rv32ui-%s: failed sub-test %0d (tohost=0x%08h, pc_ex=0x%08h)",
                   tname, th >> 1, th, dut.pc_ex);
        end
        repeat (4) @(negedge clk);
    endtask

    initial begin : watchdog
        #500_000_000;
        $fatal(1, "Watchdog timeout");
    end

    initial begin : main
        #1;
        $display("=========== riscv-tests rv32ui compliance ===========");
        for (int i = 0; i < NUM_TESTS; i++) run_one(i);
        $display("-----------------------------------------------------");
        $display("  passed: %0d   failed: %0d   (of %0d)", pass_cnt, fail_cnt, NUM_TESTS);
        if (fail_cnt == 0) $display("  *** ALL rv32ui TESTS PASSED ***");
        else               $display("  *** %0d rv32ui TEST(S) FAILED ***", fail_cnt);
        $display("=====================================================");
        $finish;
    end
endmodule